      defaultTemplate: options.defaultTemplate,
      defaultLayout: options.defaultLayout,
      pages: [],
      plugins: [],
      shared: {},
      engine: this,
    };
    const resolved: Plugin[] = [];
    for (const entry of plugins) {
      const plugin = typeof entry === 'function' ? entry(context) : entry;
      resolved.push(plugin);
